insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('SG:chef','2026-08-11',0,0,0,0,15,0,0,0,4,19,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 34341 Chef (excluding pastry chef) is the primary general-chef anchor; pastry chef 34343 remains a separate reference.','entry_level_basis','Chef work is practically accessible through culinary training and supervised kitchen experience; no approved SG programme link is currently present.','qualification_note','There is no universal Chef occupational licence. In SFA-licensed food businesses, anyone handling or preparing food must meet WSQ Food Safety Course Level 1 training/retraining requirements and be registered as a Food Handler.','market_scope','No shortage, vacancy, salary or growth points are inferred from food-safety regulation.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:cook','2026-08-11',0,0,0,0,15,0,0,0,4,19,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 51201 Cook is the direct general-cook anchor; 51202 Senior cook remains a separate seniority reference.','entry_level_basis','Cook is a practical kitchen occupation that can be entered through vocational training and supervised experience; no approved SG programme link is currently present.','qualification_note','There is no universal Cook occupational licence, but food handlers in SFA-licensed establishments must complete the required food-safety training and registration.','market_scope','Food-handler compliance is not treated as labour-demand evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:hotel-manager','2026-08-11',0,0,0,0,10,0,0,0,3,13,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 14110 Hotel operations/Lodging services manager directly anchors the canonical hotel-management role.','entry_level_basis','One approved Hospitality and Tourism Management programme is retained as a related pathway; management roles normally require operational responsibility in addition to study.','qualification_note','Singapore regulates hotel operations through establishment/operator licensing. CampCareer does not treat the broad Hotel Manager employee role as universally requiring a personal occupational licence.','market_scope','No hotel-demand, salary or vacancy figures are scored in the foundation phase.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:restaurant-manager','2026-08-11',0,0,0,0,10,0,0,0,3,13,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 14121 Restaurant manager directly anchors restaurant operations management.','entry_level_basis','One approved Hospitality and Tourism Management programme is a related pathway; practical food-service operations and supervisory experience remain important.','qualification_note','Food Shop licences attach to the food business/operator, not every Restaurant Manager personally. A manager who handles food or is appointed as a Food Hygiene Officer can have separate mandatory SFA training and registration requirements.','market_scope','Food-safety licensing is not converted into demand or salary evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:baker','2026-08-11',0,0,0,0,15,0,0,0,4,19,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 75121 Baker directly anchors bread and baking production; 75122 Pastry/Confectionery maker remains separate.','entry_level_basis','Baking is a practical trade accessible through vocational training and supervised production experience; no approved SG programme link is currently present.','qualification_note','There is no universal Baker occupational licence. Bakers working as Food Handlers in SFA-licensed retail or manufacturing establishments must meet food-safety training/retraining and registration requirements.','market_scope','No labour-market credit is inferred from food establishment regulation.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:tourism-manager','2026-08-11',0,0,0,0,10,0,0,0,4,14,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','Singapore has no single five-digit SSOC occupation titled Tourism Manager. CampCareer preserves 14392 Travel agency manager and 14322 Attractions manager as non-rollup references for the broader tourism-product and visitor-experience scope.','entry_level_basis','One approved Hospitality and Tourism Management programme is retained as a related pathway; managerial tourism roles commonly require sector and commercial experience.','qualification_note','Travel Agent licensing applies to the business of supplying travel arrangements or tours, while Tourist Guide licensing applies to individuals personally providing remunerated guiding services. Neither is treated as a universal personal licence for every Tourism Manager.','market_scope','The two management references are not aggregated into a fabricated exact tourism-manager market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:event-planner','2026-08-11',0,0,0,0,15,0,0,0,5,20,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','SSOC 33320 Exhibition/Conference/Event planner directly covers planning and coordinating conferences, exhibitions and events; 14391 Event manager is retained as a separate managerial-seniority reference.','entry_level_basis','Event planning is accessible through event, hospitality, communications or business preparation plus practical delivery experience. One approved hospitality programme is related.','qualification_note','There is no universal personal occupational registration for Event Planners. Venue, public-space, liquor, entertainment or other event-specific permits remain separate.','market_scope','Event-specific permitting does not establish shortage or demand.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11'),
('SG:hospitality-supervisor','2026-08-11',0,0,0,0,15,0,0,0,4,19,'career-opportunity-sg-v1','provisional',jsonb_build_object('classification_scope','Singapore does not have one cross-venue five-digit Hospitality Supervisor occupation. CampCareer uses kitchen operations head/supervisor 34342, waiter supervisor 51311, gaming supervisor 51701 and hotel housekeeping matron 51503 as non-rollup references.','entry_level_basis','Frontline hospitality supervision is commonly reached through operational experience and vocational or hospitality study; one approved Hospitality and Tourism Management programme is related.','qualification_note','There is no universal Hospitality Supervisor occupational licence. Supervisors who handle food, or who are appointed as Food Hygiene Officers in establishments that require one, can have mandatory SFA food-safety certification and registration obligations.','market_scope','Distinct supervisor occupations are not aggregated into unsupported labour-market metrics.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-11')
